do $$ begin create type public.person_type as enum ('student','academic_staff','administrative_staff','guest','vip'); exception when duplicate_object then null; end $$;
alter type public.app_role add value if not exists 'photographer';
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,organization_type text default 'university',primary_color text default '#D4A843',secondary_color text default '#173B62',logo_url text,active boolean default true,created_at timestamptz default now());
alter table public.profiles add column if not exists organization_id uuid references public.organizations(id);alter table public.profiles add column if not exists person_type public.person_type default 'student';alter table public.profiles add column if not exists reference_number text;alter table public.profiles add column if not exists department text;
alter table public.events add column if not exists organization_id uuid references public.organizations(id);alter table public.events add column if not exists event_type text default 'graduation';
alter table public.seats add column if not exists organization_id uuid references public.organizations(id);alter table public.bookings add column if not exists organization_id uuid references public.organizations(id);alter table public.bookings add column if not exists payment_status text default 'not_required';alter table public.payments add column if not exists organization_id uuid references public.organizations(id);alter table public.tickets add column if not exists organization_id uuid references public.organizations(id);alter table public.entry_scans add column if not exists organization_id uuid references public.organizations(id);
create table if not exists public.people_directory(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),profile_id uuid references public.profiles(id),email text,full_name text not null,person_type public.person_type not null,reference_number text,college text,department text,program text,phone text,created_at timestamptz default now(),unique(organization_id,email));
alter table public.bookings add column if not exists person_id uuid references public.people_directory(id);alter table public.tickets add column if not exists person_id uuid references public.people_directory(id);
create table if not exists public.fittings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),event_id uuid not null references public.events(id),person_id uuid not null references public.people_directory(id),gown_size text,cap_size text,hood_color text,status text default 'pending',notes text,updated_by uuid references public.profiles(id),updated_at timestamptz default now(),unique(event_id,person_id));
create table if not exists public.photo_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),event_id uuid not null references public.events(id),person_id uuid not null references public.people_directory(id),status text default 'not_scheduled',package_name text,photo_url text,notes text,updated_by uuid references public.profiles(id),updated_at timestamptz default now(),unique(event_id,person_id));
create table if not exists public.vip_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),event_id uuid references public.events(id),person_id uuid references public.people_directory(id),seat_id uuid references public.seats(id),protocol_rank int,arrival_status text default 'expected',notes text,unique(event_id,person_id));
create table if not exists public.event_services(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),event_id uuid references public.events(id),name text not null,provider_name text,status text,contact_phone text,notes text);
create table if not exists public.event_schedule(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),event_id uuid references public.events(id),title text not null,start_time timestamptz,end_time timestamptz,location text,description text);
create or replace function public.current_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from profiles where id=auth.uid()$$;
alter table public.people_directory enable row level security;alter table public.fittings enable row level security;alter table public.photo_sessions enable row level security;alter table public.vip_assignments enable row level security;alter table public.event_services enable row level security;alter table public.event_schedule enable row level security;alter table public.organizations enable row level security;
create policy org_select on public.organizations for select to authenticated using(id=current_org() or current_role()='admin');
create policy people_select on public.people_directory for select to authenticated using(organization_id=current_org());create policy people_write on public.people_directory for all to authenticated using(organization_id=current_org() and current_role() in('admin','regcom')) with check(organization_id=current_org());
create policy fitting_select on public.fittings for select to authenticated using(organization_id=current_org() and (current_role() in('admin','regcom','tailor') or person_id in(select id from people_directory where profile_id=auth.uid())));create policy fitting_write on public.fittings for all to authenticated using(organization_id=current_org() and current_role() in('admin','regcom','tailor')) with check(organization_id=current_org());
create policy photo_select on public.photo_sessions for select to authenticated using(organization_id=current_org() and (current_role() in('admin','regcom','photographer') or person_id in(select id from people_directory where profile_id=auth.uid())));create policy photo_write on public.photo_sessions for all to authenticated using(organization_id=current_org() and current_role() in('admin','regcom','photographer')) with check(organization_id=current_org());
create policy vip_select on public.vip_assignments for select to authenticated using(organization_id=current_org() and current_role() in('admin','vip'));create policy vip_write on public.vip_assignments for all to authenticated using(organization_id=current_org() and current_role() in('admin','vip')) with check(organization_id=current_org());
create policy service_select on public.event_services for select to authenticated using(organization_id=current_org());create policy service_write on public.event_services for all to authenticated using(organization_id=current_org() and current_role() in('admin','land')) with check(organization_id=current_org());
create policy schedule_select on public.event_schedule for select to authenticated using(organization_id=current_org());create policy schedule_write on public.event_schedule for all to authenticated using(organization_id=current_org() and current_role()='admin') with check(organization_id=current_org());
alter publication supabase_realtime add table public.people_directory;alter publication supabase_realtime add table public.fittings;alter publication supabase_realtime add table public.photo_sessions;alter publication supabase_realtime add table public.vip_assignments;
